-- CDSCO and NPPA: six combined questions split (new CD07-CD09, NP08-NP10).
update public.hub_chk_points set q='Are the ONDLS / SUGAM portal logins active?', why='All licences now run on these portals. Losing the login stops every application.', law='CDSCO ONDLS', evidence='Portal login list (no passwords)', updated_at=now() where code='CD01';
update public.hub_chk_points set q='Has every ''Not of Standard Quality'' notice been answered?', why='Unanswered notices go straight to court.', law='D&C Act s.18, s.27', evidence='NSQ file', updated_at=now() where code='CD04';
update public.hub_chk_points set q='Are WHO-GMP certificates valid for the products we export?', why='Buyers and tenders reject expired certificates.', law='WHO-GMP scheme (CDSCO/State)', evidence='WHO-GMP certificates', updated_at=now() where code='CD05';
update public.hub_chk_points set q='Is the MRP of every scheduled (NLEM) product at or below the NPPA ceiling price?', why='Overcharging is recovered with interest plus penalty.', law='DPCO 2013 para 13, 16', evidence='Price working sheet', updated_at=now() where code='NP01';
update public.hub_chk_points set q='Is a current price list (Form V) issued to dealers?', why='A missing price list is a separate violation.', law='DPCO 2013 para 24, 25', evidence='Price list issued to dealers', updated_at=now() where code='NP03';
update public.hub_chk_points set q='Is the firm registered on NPPA''s IPDMS portal?', why='Quarterly and yearly NPPA forms can only be filed there.', law='DPCO 2013 para 29', evidence='IPDMS registration', updated_at=now() where code='NP04';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CD07','CDSCO (Central)','Are the ONDLS / SUGAM portal logins linked to the owner''s email and mobile (not an agent''s)?','If an agent holds the login, losing the agent means losing access to every licence application.','CDSCO ONDLS','drug_mfg|cos_mfg|drug_sale',array['fda']::text[],'M','Portal registered email and mobile (screenshot)',9770,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CD08','CDSCO (Central)','Has the batch been recalled for every ''Not of Standard Quality'' notice?','Unanswered notices go straight to court.','D&C Act s.18, s.27','drug_mfg|drug_sale',array['fda']::text[],'H','Recall record',9771,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('CD09','CDSCO (Central)','Are CoPP certificates valid for the products we export?','Buyers and tenders reject expired certificates.','WHO-GMP scheme (CDSCO/State)','drug_mfg&exporter',array['fda']::text[],'M','CoPP certificates',9772,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('NP08','NPPA (Pricing)','Is the MRP updated each April when the ceiling prices are revised?','Overcharging is recovered with interest plus penalty.','DPCO 2013 para 13, 16','drug_mfg',array[]::text[],'H','Yearly price revision record',9773,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('NP09','NPPA (Pricing)','Is the current price list (Form V) filed with NPPA?','A missing price list is a separate violation.','DPCO 2013 para 24, 25','drug_mfg',array[]::text[],'M','Form V acknowledgement',9774,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('NP10','NPPA (Pricing)','Is the product data on IPDMS up to date?','Quarterly and yearly NPPA forms can only be filed there.','DPCO 2013 para 29','drug_mfg',array[]::text[],'M','IPDMS product data screenshot',9775,true,null) on conflict (code) do nothing;
