','TP10','TP07','TP11','TP08','PS01','PS02','PS03','PS04','PS09','PS05','PS06','PS07','PS08','PS10','BD01','BD02','BD07','BD03','BD04','BD05','BD06','MU01','MU02','MU03','MU10','MU11','MU12','MU04','MU13','MU14','MU05','MU06','MU15','MU07','MU16','MU08','MU09','MU17','SM01','SM07','SM02','SM03','SM08','SM04','SM09','SM05','SM10','SM11','SM06','SM12','LG01','LG08','LG02','LG03','LG09','LG04','LG10','LG05','LG11','LG06','LG07']::text[]) with ordinality as o(code, ord) where p.code = o.code and p.sort <> o.ord - 1;
-- Existing answers: those that covered both halves are copied to the new question; NP03 and NP04 'No' (with open actions) are flagged for re-check.
insert into public.hub_chk_answers(firm_id, code, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at)
  select firm_id, t.c, answer, note, ref_no, proof_link, proof_path, proof_name, answered_by, answered_by_name, answered_at from public.hub_chk_answers, (values ('CD01','CD07'),('CD04','CD08'),('NP01','NP08')) as t(f,c) where code=t.f and answer in ('yes','na') on conflict do nothing;
update public.hub_chk_answers set stale=true, stale_reason='question was split in two, please confirm which part this No is about' where code in ('NP03','NP04') and firm_id='VP';
